"use client";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Command,
  CommandEmpty,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import { Popover, PopoverTrigger } from "@/components/ui/popover";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ComboboxPopoverContent } from "./popover";
import { cn } from "@/lib/utils";
import { Check, ChevronsUpDown, Loader2, X } from "lucide-react";
import type { ReactNode } from "react";
import { Fragment, useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import {
  DEFAULT_CLEAR_BUTTON_LABEL,
  DEFAULT_EMPTY_OPTION_LABEL,
  DEFAULT_EMPTY_MESSAGE,
  DEFAULT_LOAD_MORE_LABEL,
  DEFAULT_LOADING_MESSAGE,
  DEFAULT_PLACEHOLDER,
  DEFAULT_REMOTE_ERROR_MESSAGE,
  DEFAULT_SEARCH_PLACEHOLDER,
} from "./defaults";
import { useRemoteItems } from "./remote";
import type {
  ComboboxOption,
  ComboboxProps,
  ComboboxValueType,
  MenuItemConfig,
  RemoteConfig,
  SelectedItemConfig,
} from "./types";
import {
  buildSearchableValue,
  getButtonLabelNode,
  getButtonLabelPlainText,
  getButtonStartNode,
  getLabelNode,
  getMultiSelectionPlainText,
  getRawValueFromItem,
  isSameComboboxValue,
} from "./utils";

interface OptionEntry<T> {
  option: ComboboxOption<ComboboxValueType<T>>;
  item: T;
}

/** Trigger label layout shared by single and multi selection modes. */
function TriggerLabel({ label, startNode }: { label: ReactNode; startNode?: ReactNode | null }) {
  if (startNode) {
    return (
      <span className='flex min-w-0 items-center gap-2 py-0.5'>
        <span className='shrink-0 flex items-center'>{startNode}</span>
        <span className='min-w-0 truncate'>{label}</span>
      </span>
    );
  }
  return <span className='min-w-0 truncate block'>{label}</span>;
}

function hasSingleValue(value: unknown): boolean {
  return (
    value !== null && value !== undefined && !(typeof value === "string" && value.trim() === "")
  );
}

function hasFallbackLabel(label: ReactNode): boolean {
  if (label === null || label === undefined) return false;
  if (typeof label === "string") return label.trim().length > 0;
  return true;
}

/**
 * Defers onChange so the popover unmounts before consumers re-render (e.g. a
 * react-hook-form validation state swap) to avoid a visible flicker/teardown race.
 */
function deferSingleSelectChange(callback: () => void) {
  window.setTimeout(callback, 0);
}

function FallbackLabel({ children }: { children: ReactNode }) {
  return <span className='min-w-0 truncate block'>{children}</span>;
}

/**
 * Advanced Combobox — docs: https://github.com/FernaandoJr/advanced-combobox/blob/main/docs/combobox.md
 * The full API reference is also installed as `./combobox.md` next to this
 * file: every prop, config object (`remote`, `menuItemConfig`, `pagination`,
 * `multipleConfig`, `selectedItemConfig`) and callback documented with types,
 * defaults and semantics.
 */
export function Combobox<T>({
  placeholder: placeholderProp,
  showEmptyOption,
  showClearButton,
  emptyOptionLabel,
  clearButtonLabel,
  searchPlaceholder,
  emptyMessage,
  loadingMessage,
  remoteErrorMessage,
  value: controlledValue,
  onChange,
  onSelectedItemResolved,
  onBlur,
  onKeyDown,
  className,
  disabled,
  fullWidth,
  searchInput,
  pagination,
  error,
  label: labelProp,
  remote,
  options,
  menuItemConfig,
  selectedItemConfig,
  selectedFallbackLabel,
  multiple,
  multipleConfig,
  required,
  onMaxSelectionReached,
  id: idProp,
  name,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
}: ComboboxProps<T>) {
  const placeholder = placeholderProp ?? DEFAULT_PLACEHOLDER;
  const generatedId = useId();
  const id = idProp ?? generatedId;
  const [portalContainer, setPortalContainer] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  const [searchValue, setSearchValue] = useState("");
  const [internalSingle, setInternalSingle] = useState<ComboboxValueType<T> | null | undefined>(
    undefined,
  );
  const [internalMulti, setInternalMulti] = useState<ComboboxValueType<T>[]>([]);
  const { items: remoteItems, error: remoteError, isLoading } = useListRemoteItems(
    remote,
    searchValue,
    open,
  );

  const isMulti = multiple === true;
  const isControlled = controlledValue !== undefined;
  const itemConfig = menuItemConfig;
  const searchKeys = itemConfig.searchProperties || itemConfig.label;
  const searchText = searchPlaceholder ?? DEFAULT_SEARCH_PLACEHOLDER;
  const clearOptionText = emptyOptionLabel ?? DEFAULT_EMPTY_OPTION_LABEL;
  const clearButtonText = clearButtonLabel ?? DEFAULT_CLEAR_BUTTON_LABEL;
  const emptyText = isLoading
    ? (loadingMessage ?? DEFAULT_LOADING_MESSAGE)
    : remoteError
      ? (remoteErrorMessage ?? DEFAULT_REMOTE_ERROR_MESSAGE)
      : (emptyMessage ?? DEFAULT_EMPTY_MESSAGE);

  const valueSingle = useMemo(() => {
    if (!isControlled) return internalSingle;
    return Array.isArray(controlledValue) ? undefined : (controlledValue ?? undefined);
  }, [isControlled, controlledValue, internalSingle]);

  // Option and its source item resolved together in one O(n) pass over the data.
  // options win over remote items when both are provided and non-empty.
  const optionEntries = useMemo(
    (): OptionEntry<T>[] =>
      (options && options.length > 0 ? options : remoteItems).map((item) => ({
        option: {
          value: getRawValueFromItem(item, itemConfig.value),
          label: getLabelNode(item, itemConfig),
          searchableValue: buildSearchableValue(item, searchKeys),
        },
        item,
      })),
    [options, remoteItems, itemConfig, searchKeys],
  );
  const isInitialRemoteLoading = Boolean(remote && isLoading && optionEntries.length === 0);
  const paginationEnabled = Boolean(pagination);
  const serverPaginationEnabled = pagination?.mode === "server";
  const controlledSearchEnabled = paginationEnabled || remote?.searchOnInput === true;
  const paginationPageSize = pagination ? Math.max(1, pagination.pageSize) : 0;
  const [visibleOptionCount, setVisibleOptionCount] = useState(paginationPageSize);
  const filteredEntries = useMemo(() => {
    if (!paginationEnabled || serverPaginationEnabled) return optionEntries;
    const query = searchValue.trim().toLowerCase();
    if (!query) return optionEntries;
    return optionEntries.filter((entry) =>
      `${String(entry.option.value)} ${entry.option.searchableValue ?? ""}`
        .toLowerCase()
        .includes(query),
    );
  }, [optionEntries, paginationEnabled, serverPaginationEnabled, searchValue]);
  const effectiveVisibleOptionCount = Math.max(paginationPageSize, visibleOptionCount);
  const visibleEntries =
    paginationEnabled && !serverPaginationEnabled
      ? filteredEntries.slice(0, effectiveVisibleOptionCount)
      : filteredEntries;
  const hasMoreOptions = serverPaginationEnabled
    ? Boolean(pagination?.hasMore)
    : paginationEnabled && effectiveVisibleOptionCount < filteredEntries.length;

  const selectedEntry = useMemo(
    () => optionEntries.find((entry) => isSameComboboxValue(entry.option.value, valueSingle)) ?? null,
    [optionEntries, valueSingle],
  );
  const selectedOption = isMulti ? null : selectedEntry?.option ?? null;

  const lastResolvedKey = useRef<string | null>(null);

  useEffect(() => {
    if (isMulti || !hasSingleValue(valueSingle)) {
      lastResolvedKey.current = null;
      return;
    }
    if (!selectedEntry) return;
    // Notify at most once per resolved value: inline callbacks that change
    // identity every render must not re-trigger effect loops.
    const key = String(selectedEntry.option.value);
    if (lastResolvedKey.current === key) return;
    lastResolvedKey.current = key;
    onSelectedItemResolved?.(selectedEntry.item);
  }, [isMulti, onSelectedItemResolved, selectedEntry, valueSingle]);

  const selectedValues = useMemo((): ComboboxValueType<T>[] => {
    if (!isMulti) return [];
    return isControlled ? (Array.isArray(controlledValue) ? controlledValue : []) : internalMulti;
  }, [isMulti, isControlled, controlledValue, internalMulti]);
  // Entries in the same order as selectedValues (order the selection was built).
  const selectedEntries = useMemo(
    () =>
      selectedValues
        .map((value) => optionEntries.find((entry) => isSameComboboxValue(entry.option.value, value)))
        .filter((entry): entry is OptionEntry<T> => entry != null),
    [selectedValues, optionEntries],
  );
  const showInlineClearButton =
    showClearButton === true && !isMulti && !disabled && hasSingleValue(valueSingle);

  const resetSearchState = () => {
    if (!controlledSearchEnabled) return;
    setSearchValue("");
    if (paginationEnabled) {
      setVisibleOptionCount(paginationPageSize);
      pagination?.onSearchChange?.("");
    }
  };

  const resolveItems = (values: ComboboxValueType<T>[]): T[] =>
    values.flatMap((value) => {
      const entry = optionEntries.find((e) => isSameComboboxValue(e.option.value, value));
      return entry ? [entry.item] : [];
    });

  const handleChange = (option: ComboboxOption<ComboboxValueType<T>>, item: T) => {
    if (isMulti) {
      const withoutOption = selectedValues.filter((v) => !isSameComboboxValue(v, option.value));
      const isRemoving = withoutOption.length < selectedValues.length;
      if (!isRemoving) {
        const maxSelection = multipleConfig?.maxSelection;
        if (maxSelection && selectedValues.length >= maxSelection) {
          onMaxSelectionReached?.();
          return;
        }
      }
      const next = isRemoving ? withoutOption : [...withoutOption, option.value];
      if (!isControlled) setInternalMulti(next);
      onChange?.(next, resolveItems(next));
    } else {
      if (!isControlled) setInternalSingle(option.value);
      resetSearchState();
      setOpen(false);
      deferSingleSelectChange(() => {
        onChange?.(option.value, item);
      });
    }
  };

  const handleOpenChange = (isOpen: boolean) => {
    setOpen(isOpen);
    if (!isOpen) {
      resetSearchState();
      onBlur?.();
    }
  };

  const handleSearchValueChange = (nextValue: string) => {
    setSearchValue(nextValue);
    setVisibleOptionCount(paginationPageSize);
    pagination?.onSearchChange?.(nextValue);
  };

  const handleClearSelection = () => {
    if (isMulti) return;
    if (!isControlled) setInternalSingle(null);
    resetSearchState();
    setOpen(false);
    deferSingleSelectChange(() => {
      onChange?.(null, null);
    });
  };

  const handleTriggerContainerRef = useCallback((node: HTMLDivElement | null) => {
    const nextContainer = node?.closest<HTMLElement>("[data-slot='dialog-content']") ?? null;
    setPortalContainer((current) => (current === nextContainer ? current : nextContainer));
  }, []);

  const buttonContent = useMemo<ReactNode>(() => {
    if (isMulti) {
      if (selectedValues.length === 0) return placeholder || "";
      if (selectedEntries.length < selectedValues.length && hasFallbackLabel(selectedFallbackLabel)) {
        return <FallbackLabel>{selectedFallbackLabel}</FallbackLabel>;
      }
      if (selectedEntries.length === 1) {
        const { item } = selectedEntries[0];
        const buttonLabel = getButtonLabelNode(item, itemConfig, selectedItemConfig);
        const buttonStartNode = getButtonStartNode(item, itemConfig, selectedItemConfig);
        return <TriggerLabel label={buttonLabel} startNode={buttonStartNode} />;
      }
      const maxVisibleItems = multipleConfig?.maxVisibleItems;
      const entriesToShow = maxVisibleItems
        ? selectedEntries.slice(0, maxVisibleItems)
        : selectedEntries;
      const itemsSeparator = selectedItemConfig?.multipleSeparator;
      const overflowCount =
        maxVisibleItems && selectedEntries.length > maxVisibleItems
          ? selectedEntries.length - maxVisibleItems
          : 0;

      // Common path: every label resolves to plain text → a single truncated
      // line that ellipsizes exactly when the trigger runs out of space.
      const plainLabel = getMultiSelectionPlainText(
        entriesToShow.map(({ item }) => item),
        itemConfig,
        selectedItemConfig,
        itemsSeparator ?? ", ",
      );
      if (plainLabel != null) {
        return (
          <span className='flex min-w-0 max-w-full items-center'>
            <span className='min-w-0 truncate'>{plainLabel}</span>
            {overflowCount > 0 && (
              <span className='ml-1 shrink-0 text-muted-foreground'>+{overflowCount}</span>
            )}
          </span>
        );
      }
      // Fallback for ReactNode labels: one line clipped at the container edge;
      // only the last visible item may shrink, so it carries the truncation.
      return (
        <span
          className={cn(
            "flex min-w-0 max-w-full items-center overflow-hidden",
            !itemsSeparator && "gap-1",
          )}
        >
          {entriesToShow.map(({ item, option }, index) => {
            const label = getButtonLabelNode(item, itemConfig, selectedItemConfig);
            const isLast = index === entriesToShow.length - 1;
            return (
              <span
                key={String(option.value)}
                className={cn("flex min-w-0 items-center", !isLast && "shrink-0")}
              >
                {index > 0 && itemsSeparator && (
                  <span className='mx-1 shrink-0 text-muted-foreground'>{itemsSeparator}</span>
                )}
                <span className={cn("truncate", isLast ? "min-w-0" : "max-w-28")}>{label}</span>
              </span>
            );
          })}
          {overflowCount > 0 && (
            <span className='ml-1 shrink-0 text-muted-foreground'>+{overflowCount}</span>
          )}
        </span>
      );
    }
    if (!selectedEntry) {
      if (hasSingleValue(valueSingle) && hasFallbackLabel(selectedFallbackLabel)) {
        return <FallbackLabel>{selectedFallbackLabel}</FallbackLabel>;
      }
      return placeholder || "";
    }
    return (
      <TriggerLabel
        label={getButtonLabelNode(selectedEntry.item, itemConfig, selectedItemConfig)}
        startNode={getButtonStartNode(selectedEntry.item, itemConfig, selectedItemConfig)}
      />
    );
  }, [
    isMulti,
    selectedEntry,
    selectedValues,
    selectedEntries,
    optionEntries,
    itemConfig,
    selectedItemConfig,
    multipleConfig,
    placeholder,
    selectedFallbackLabel,
    valueSingle,
  ]);

  const buttonTitle = useMemo(() => {
    if (isMulti) {
      if (selectedValues.length > 0 && selectedEntries.length < selectedValues.length) {
        return typeof selectedFallbackLabel === "string" ? selectedFallbackLabel : undefined;
      }
      if (selectedEntries.length === 0) return undefined;
      const parts = selectedEntries
        .map(({ item }) => getButtonLabelPlainText(item, itemConfig, selectedItemConfig))
        .filter((value): value is string => Boolean(value));
      if (parts.length === 0) return undefined;
      return parts.join(selectedItemConfig?.multipleSeparator ?? ", ");
    }

    if (!selectedEntry) {
      if (hasSingleValue(valueSingle)) {
        return typeof selectedFallbackLabel === "string" ? selectedFallbackLabel : undefined;
      }
      return undefined;
    }
    return getButtonLabelPlainText(selectedEntry.item, itemConfig, selectedItemConfig);
  }, [
    isMulti,
    selectedEntries,
    selectedEntry,
    selectedValues,
    itemConfig,
    selectedItemConfig,
    selectedFallbackLabel,
    valueSingle,
  ]);

  return (
    <Fragment>
      {labelProp && (
        <Label htmlFor={id} className='mb-1.5 flex items-center gap-2'>
          {labelProp}
          {required && <span className='text-destructive'>*</span>}
        </Label>
      )}
      <Popover open={open} onOpenChange={handleOpenChange}>
        <div
          ref={handleTriggerContainerRef}
          className={cn("relative min-w-0 max-w-full", fullWidth ? "w-full" : "w-max")}
        >
          <PopoverTrigger asChild>
            <Button
              type='button'
              id={id}
              name={name}
              variant='outline'
              role='combobox'
              aria-expanded={open}
              aria-describedby={ariaDescribedBy}
              aria-invalid={ariaInvalid ?? (error ? true : undefined)}
              disabled={disabled}
              aria-busy={isLoading || undefined}
              onKeyDown={onKeyDown}
              className={cn(
                "justify-start text-left select-none cursor-pointer h-9 min-h-9 max-h-9 min-w-0 max-w-full overflow-hidden",
                fullWidth ? "w-full" : "min-w-70 w-max",
                showInlineClearButton && "pr-16",
                error && "text-destructive! border-destructive!",
                className,
              )}
            >
              <span
                className='flex min-w-0 max-w-full flex-1 items-center overflow-hidden font-normal'
                title={buttonTitle}
              >
                {buttonContent}
              </span>
              {isLoading ? (
                <Loader2 className='ml-2 h-4 w-4 shrink-0 animate-spin' />
              ) : (
                <ChevronsUpDown className='ml-2 h-4 w-4 shrink-0 opacity-50' />
              )}
            </Button>
          </PopoverTrigger>
          {showInlineClearButton ? (
            <Button
              type='button'
              variant='ghost'
              size='icon-xs'
              className='absolute top-1/2 right-8 z-10 -translate-y-1/2 text-muted-foreground hover:text-foreground'
              aria-label={clearButtonText}
              title={clearButtonText}
              onPointerDown={(event) => {
                event.preventDefault();
                event.stopPropagation();
              }}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                handleClearSelection();
              }}
            >
              <X aria-hidden='true' />
            </Button>
          ) : null}
        </div>
        <ComboboxPopoverContent
          className={cn("p-0 w-(--radix-popover-trigger-width)")}
          align='start'
          container={portalContainer}
        >
          <Command
            shouldFilter={!paginationEnabled && remote?.searchOnInput !== true}
            className={cn(
              "grid max-h-[min(300px,var(--radix-popover-content-available-height))]",
              searchInput ? "grid-rows-[auto_minmax(0,1fr)]" : "grid-rows-[minmax(0,1fr)]",
            )}
          >
            {searchInput ? (
              <CommandInput
                placeholder={searchText}
                value={controlledSearchEnabled ? searchValue : undefined}
                onValueChange={controlledSearchEnabled ? handleSearchValueChange : undefined}
              />
            ) : null}
            <ScrollArea
              type='scroll'
              className='min-h-0 overscroll-contain'
              onWheel={(e) => e.stopPropagation()}
              onTouchMove={(e) => e.stopPropagation()}
            >
              <CommandList
                className='max-h-none overflow-visible scroll-py-1 pr-0.5'
              >
              {isInitialRemoteLoading ? (
                <div
                  className='flex items-center justify-center gap-2 px-3 py-6 text-sm text-muted-foreground'
                  role='status'
                >
                  <Loader2 className='h-4 w-4 animate-spin' />
                  <span>{emptyText}</span>
                </div>
              ) : (
                <>
                  {remoteError ? (
                    <div role='alert' className='px-3 py-4 text-sm text-muted-foreground'>
                      {remoteErrorMessage ?? DEFAULT_REMOTE_ERROR_MESSAGE}
                    </div>
                  ) : (
                    <CommandEmpty>{emptyText}</CommandEmpty>
                  )}
                  {!isMulti && showEmptyOption ? (
                    <CommandItem
                      value='__combobox-empty__'
                      keywords={[clearOptionText]}
                      className='min-w-0 cursor-pointer'
                      onSelect={() => handleClearSelection()}
                    >
                      <span className='min-w-0 flex-1 truncate'>{clearOptionText}</span>
                      <Check
                        className={cn(
                          "ml-2 h-4 w-4 shrink-0",
                          !selectedOption ? "opacity-100" : "opacity-0",
                        )}
                      />
                    </CommandItem>
                  ) : null}
                  {visibleEntries.map(({ option, item }) => {
                    const valueStr = String(option.value);
                    const optionDisabled = itemConfig.isOptionDisabled?.(item) ?? false;
                    const startNode = itemConfig.customStartNode?.(item) ?? null;

                    if (isMulti) {
                      const checked = selectedValues.some((v) =>
                        isSameComboboxValue(v, option.value),
                      );
                      return (
                        <CommandItem
                          key={valueStr}
                          value={valueStr}
                          keywords={option.searchableValue ? [option.searchableValue] : undefined}
                          disabled={optionDisabled}
                          className={cn(
                            "min-w-0 cursor-pointer",
                            optionDisabled && "cursor-not-allowed",
                          )}
                          onSelect={() => {
                            if (optionDisabled) return;
                            handleChange(option, item);
                          }}
                          aria-selected={checked}
                        >
                          <Checkbox
                            checked={checked}
                            className='mr-2 shrink-0 pointer-events-none'
                            aria-hidden
                          />
                          {startNode && <span className='mr-2 shrink-0'>{startNode}</span>}
                          <span className='min-w-0 flex-1 truncate'>{option.label}</span>
                        </CommandItem>
                      );
                    }

                    return (
                      <CommandItem
                        key={valueStr}
                        value={valueStr}
                        keywords={option.searchableValue ? [option.searchableValue] : undefined}
                        disabled={optionDisabled}
                        className={cn(
                          "min-w-0 cursor-pointer",
                          optionDisabled && "cursor-not-allowed",
                        )}
                        onSelect={() => {
                          if (optionDisabled) return;
                          handleChange(option, item);
                        }}
                      >
                        {startNode && <span className='mr-2 shrink-0'>{startNode}</span>}
                        <span className='min-w-0 flex-1 truncate'>{option.label}</span>
                        <Check
                          className={cn(
                            "ml-2 h-4 w-4 shrink-0",
                            isSameComboboxValue(valueSingle, option.value)
                              ? "opacity-100"
                              : "opacity-0",
                          )}
                        />
                      </CommandItem>
                    );
                  })}
                  {hasMoreOptions ? (
                    <div className='border-t p-1'>
                      <Button
                        type='button'
                        size='sm'
                        variant='ghost'
                        className='w-full cursor-pointer'
                        disabled={pagination?.isLoadingMore}
                        onClick={() => {
                          if (serverPaginationEnabled) {
                            pagination?.onLoadMore?.();
                            return;
                          }
                          setVisibleOptionCount((current) => current + paginationPageSize);
                        }}
                      >
                        {pagination?.isLoadingMore ? (
                          <Loader2 className='mr-2 size-4 animate-spin' />
                        ) : null}
                        {pagination?.loadMoreLabel ?? DEFAULT_LOAD_MORE_LABEL}
                      </Button>
                    </div>
                  ) : null}
                </>
              )}
            </CommandList>
            </ScrollArea>
          </Command>
        </ComboboxPopoverContent>
      </Popover>
    </Fragment>
  );
}

/**
 * Maps the declarative `remote` config onto the canonical remote engine:
 * key = identifier (+ search text with searchOnInput), enabled = open (or
 * eager on mount with disableLazyFetch), plus optional per-open revalidation.
 */
function useListRemoteItems<T>(
  remote: RemoteConfig<T> | undefined,
  searchValue: string,
  open: boolean,
) {
  const searchOnInput = remote?.searchOnInput === true;
  const normalizedSearchValue = searchValue.trim();
  const cacheKey = remote
    ? searchOnInput
      ? `${remote.identifier}:${normalizedSearchValue}`
      : remote.identifier
    : null;
  const enabled =
    Boolean(remote) &&
    (searchOnInput ? open : open || remote?.disableLazyFetch === true);
  return useRemoteItems<T>(
    remote

      ? (signal) => remote.optionsFn(searchOnInput ? normalizedSearchValue : undefined, signal)
      : undefined,
    cacheKey,
    { enabled, refreshOnOpen: remote?.refreshOnOpen === true },
  );
}

import * as PopoverPrimitive from "@radix-ui/react-popover";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/**
 * Combobox-specific popover content rendered through the Radix Portal directly.
 *
 * Lives inside the item (instead of reusing `@/components/ui/popover`s
 * PopoverContent) because the official shadcn wrapper does not forward a portal
 * `container`, which the combobox needs to escape Dialog/Sheet overflow.
 */
export function ComboboxPopoverContent({
  container,
  className,
  children,
  align = "start",
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content> & {
  /** Portal container override (e.g. a Dialog content node when the popover must escape overflow). */
  container?: HTMLElement | null;
}) {
  return (
    <PopoverPrimitive.Portal container={container ?? undefined}>
      <PopoverPrimitive.Content
        data-combobox-content=''
        align={align}
        className={cn(
          "bg-popover text-popover-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 origin-(--radix-popover-content-transform-origin) rounded-md border p-4 shadow-md outline-hidden",
          "p-0 w-(--radix-popover-trigger-width)",
          className,
        )}
        {...props}
      >
        {children}
      </PopoverPrimitive.Content>
    </PopoverPrimitive.Portal>
  );
}

import type { ReactNode } from "react";

/** Inferred type of the option value from item T and menuItemConfig.value. */
export type ComboboxValueType<T> = T[MenuItemConfig<T>["value"]];

/** Single selectable option (internal shape; options/remote items are mapped via menuItemConfig). */
export interface ComboboxOption<V = string> {
  value: V;
  label: ReactNode;
  /** String used for search filtering. */
  searchableValue?: string;
}

/**
 * Config for loading options from a remote API.
 * The component keeps a small in-memory cache per identifier (plus search value
 * when searchOnInput is on) so reopening the dropdown does not hit the API again.
 * Set refreshOnOpen to true to revalidate on every open instead.
 */
export interface RemoteConfig<T> {
  /** Unique id for this remote config; used as the cache key. */
  identifier: string;
  /** Returns raw items; component maps them with menuItemConfig. */
  optionsFn: (searchValue?: string, signal?: AbortSignal) => Promise<T[]>;
  /** If true, fetches data on mount. If false, fetches on dropdown open. */
  disableLazyFetch?: boolean;
  /** When true, the current search text is sent to optionsFn instead of filtering one page locally. */
  searchOnInput?: boolean;
  /** When true, refetches every time the dropdown opens (cache is ignored). Defaults to false. */
  refreshOnOpen?: boolean;
}

/**
 * Maps type T to value and label for menu items.
 * Keys are type-checked; value type is preserved (number, string, etc.); label is built from the given keys (or customLabel).
 */
export interface MenuItemConfig<T> {
  /** Key of T used as option value (e.g. "id", "code"). Type is preserved in Combobox value/onChange. */
  value: keyof T;
  /** Keys of T used to build the label (e.g. ["sku", "name"]). Joined with separator. Ignored when customLabel is set. */
  label: (keyof T)[];
  /** Separator between label parts. Default: " - " (with spaces). */
  separator?: string;
  /** When true, no spaces around separator. */
  disableSpaceBetween?: boolean;
  /** Custom ReactNode per item (overrides label). Use for badges, images, etc. */
  customLabel?: (item: T) => ReactNode;
  /** ReactNode at the start of each menu item (e.g. icon, avatar). */
  customStartNode?: (item: T) => ReactNode;
  /** Keys of T used for search filtering. Defaults to label keys when omitted. */
  searchProperties?: (keyof T)[];
  /** When set, menu items for which this returns true are shown but not selectable. */
  isOptionDisabled?: (item: T) => boolean;
}

/**
 * Config for multiple selection. Only used when multiple === true.
 * When maxVisibleItems is omitted, behavior is automatic (shows all selected items).
 */
export interface MultipleConfig {
  /** Max number of items that can be selected. Omit = unlimited. */
  maxSelection?: number;
  /** How many selected items to show on the trigger before "+N". Omit = automatic behavior. */
  maxVisibleItems?: number;
}

/** Optional pagination for large option lists. Defaults to client-side pagination. */
export interface PaginationConfig {
  /** Number of matching options rendered initially and by each load-more action. */
  pageSize: number;
  /** Optional label for the load-more action. */
  loadMoreLabel?: string;
  /** Server mode delegates search and loading the next page to the caller. */
  mode?: "client" | "server";
  /** Whether the server has another page. Used only in server mode. */
  hasMore?: boolean;
  /** Whether the next server page is being loaded. Used only in server mode. */
  isLoadingMore?: boolean;
  /** Loads the next server page. */
  onLoadMore?: () => void;
  /** Receives the current search text. */
  onSearchChange?: (value: string) => void;
}

/**
 * Config for the trigger button label when an item is selected.
 * Overrides menuItemConfig for display only; does not affect dropdown items.
 */
export interface SelectedItemConfig<T> {
  /** Keys of T to build the button label (e.g. ["name", "email"]). Defaults to menuItemConfig.label. */
  label?: (keyof T)[];
  /** Separator between label parts. Defaults to menuItemConfig.separator. */
  separator?: string;
  /** When true, no spaces around separator. Defaults to menuItemConfig.disableSpaceBetween. */
  disableSpaceBetween?: boolean;
  /**
   * Separator string rendered between multiple selected items in the trigger,
   * e.g. "/" or " | ". When omitted, items are separated only by spacing.
   */
  multipleSeparator?: string;
  /** Custom ReactNode for the button when selected (overrides label and menuItemConfig.customLabel). */
  customLabel?: (item: T) => ReactNode;
  /** ReactNode at the start of the button when selected (overrides menuItemConfig.customStartNode). */
  customStartNode?: (item: T) => ReactNode;
  /** When true, hides startNode on the button. Ignored if customStartNode is set. */
  disableStartNode?: boolean;
}

export interface ComboboxProps<T> {
  /** Controlled selected option value. Single: ComboboxValueType<T> or null when cleared. Multi: ComboboxValueType<T>[]. */
  value?: ComboboxValueType<T> | ComboboxValueType<T>[] | null;
  /** Id for the trigger (e.g. from FormControl). */
  id?: string;
  /** Name for the trigger when used as a form field. */
  name?: string;
  /** aria-describedby for the trigger (e.g. from FormControl). */
  "aria-describedby"?: string;
  /** aria-invalid for the trigger (e.g. from FormControl). */
  "aria-invalid"?: boolean;
  /** When true, allows multiple selections with checkboxes. */
  multiple?: boolean;
  /** When multiple is true: limits and how many items to show on the trigger. */
  multipleConfig?: MultipleConfig;
  /** When true, shows required indicator (red asterisk) next to label. */
  required?: boolean;
  /** Text shown when no option is selected. Defaults to "Select...". */
  placeholder?: string;
  /** When true in single-select mode, shows a first option that clears the current selection. */
  showEmptyOption?: boolean;
  /** When true in single-select mode, shows an inline button that clears the current selection. */
  showClearButton?: boolean;
  /** Label for the clear option. Defaults to "Clear". */
  emptyOptionLabel?: string;
  /** Accessible label / title of the inline clear button. Defaults to "Clear selection". */
  clearButtonLabel?: string;
  /** Placeholder for the dropdown search input. Defaults to "Search...". */
  searchPlaceholder?: string;
  /** Message when no options match the search. Defaults to "No results found". */
  emptyMessage?: string;
  /** Message shown while loading remote data. Defaults to "Loading...". */
  loadingMessage?: string;
  /** Message shown when loading remote data fails. */
  remoteErrorMessage?: string;
  /** Label text for the combobox trigger (associated via htmlFor/id). */
  label?: string;
  /** Disables the combobox. */
  disabled?: boolean;
  /** Extra CSS classes for the trigger button. */
  className?: string;
  /** When true, trigger button uses full width of its container. */
  fullWidth?: boolean;
  /** When true, shows search input inside the dropdown. */
  searchInput?: boolean;
  /** Pagination for the option list. Requires a positive pageSize. */
  pagination?: PaginationConfig;
  /** When true, marks the combobox as invalid (validation error). */
  error?: boolean;
  /** Raw items of type T. Value and label are derived from menuItemConfig. */
  options?: T[];
  /** Mapping from T to value/label and search. Required. */
  menuItemConfig: MenuItemConfig<T>;
  /** Overrides for how the selected item is shown in the trigger. Defaults to menuItemConfig. */
  selectedItemConfig?: SelectedItemConfig<T>;
  /** Label shown for the selected value when the selected item is not loaded yet. */
  selectedFallbackLabel?: ReactNode;
  /** Fetches options from API; items are shaped via menuItemConfig. */
  remote?: RemoteConfig<T>;
  /** Called when selection changes. Single: (value, item). Multi: (values, items[]). Value is null when single selection is cleared. */
  onChange?: (
    value: ComboboxValueType<T> | ComboboxValueType<T>[] | null | undefined,
    item: T | T[] | null,
  ) => void;
  /** Reports the complete item after controlled-value hydration, including remote options. */
  onSelectedItemResolved?: (item: T | null) => void;
  /** Called when the combobox loses focus. */
  onBlur?: () => void;
  /** Called when user tries to select beyond maxSelection (multiple only). */
  onMaxSelectionReached?: () => void;
  /** Called on key events on the trigger. */
  onKeyDown?: (event: React.KeyboardEvent) => void;
}

import type { ReactNode } from "react";
import type { MenuItemConfig, SelectedItemConfig } from "./types";

export interface BuildLabelOptions {
  separator?: string;
  disableSpaceBetween?: boolean;
}

export const DEFAULT_LABEL_SEPARATOR = " ";

/**
 * Obtém o valor de uma propriedade do item como string (para UI: Command, search, labels).
 * Se o valor for undefined ou null, retorna uma string vazia.
 */
export function getValueFromItem<T>(item: T, key: keyof T): string {
  const v = (item as Record<keyof T, unknown>)[key];
  return v !== undefined && v !== null ? String(v) : "";
}

/**
 * Obtém o valor bruto da propriedade do item (preserva tipo: number, string, etc.).
 * Usado para option.value no Combobox.
 */
export function getRawValueFromItem<T, K extends keyof T>(item: T, key: K): T[K] {
  return (item as Record<K, T[K]>)[key];
}

/**
 * Compara dois values de opção tolerando diferença de tipo (ex.: 3 vs "3").
 * Necessário porque o value controlado pode vir de um form/JSON como string
 * enquanto a opção mantém o tipo bruto (number, boolean, etc.).
 */
export function isSameComboboxValue(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a === null || a === undefined || b === null || b === undefined) return false;
  return String(a) === String(b);
}

/**
 * Resolve o item T a partir do value selecionado (string vinda do Command).
 * Compara por String(o.value) === valueStr para suportar value tipado (number, string, etc.).
 */
export function getItemByValue<T, V>(
  valueStr: string,
  allOptions: { value: V }[],
  allItems: T[] | undefined,
): T | null {
  const idx = allOptions.findIndex((o) => String(o.value) === valueStr);
  if (idx < 0) return null;
  if (allItems) return allItems[idx] ?? null;
  return (allOptions[idx] as unknown as T) ?? null;
}

/**
 * Resolve itens T a partir de uma lista de values tipados. Mantém ordem de values.
 * Compara com isSameComboboxValue para suportar number, string, etc.
 */
export function getItemsByValues<T, V>(
  values: V[],
  allOptions: { value: V }[],
  allItems: T[] | undefined,
): T[] {
  const result: T[] = [];
  for (const v of values) {
    const idx = allOptions.findIndex((o) => isSameComboboxValue(o.value, v));
    if (idx >= 0 && allItems?.[idx] != null) result.push(allItems[idx]);
  }
  return result;
}

/**
 * Builds display label from item by joining values of the given keys.
 * By default separator is rendered with spaces (e.g. "-" becomes " - ").
 * Set disableSpaceBetween: true to use separator as-is (no spaces).
 */
export function buildLabelFromKeys<T>(
  item: T,
  keys: (keyof T)[],
  options: BuildLabelOptions = {},
): string {
  const { separator = DEFAULT_LABEL_SEPARATOR, disableSpaceBetween = false } = options;
  const parts = keys.map((key) => getValueFromItem(item, key));
  const joinStr = disableSpaceBetween
    ? separator
    : separator
      ? ` ${separator} `
      : DEFAULT_LABEL_SEPARATOR;
  return parts.join(joinStr);
}

/**
 * Builds a searchable string from item by joining values of the given keys.
 * Used for filtering/searching within the combobox.
 */
export function buildSearchableValue<T>(item: T, keys: (keyof T)[]): string {
  return keys
    .map((key) => getValueFromItem(item, key))
    .join(" ")
    .toLowerCase()
    .trim();
}

/**
 * Obtém o ReactNode do label para o botão quando um item está selecionado.
 * Prioridade:
 * 1. selectedItemConfig.customLabel
 * 2. selectedItemConfig.label (com buildLabelFromKeys)
 * 3. menuItemConfig.customLabel
 * 4. menuItemConfig.label (com buildLabelFromKeys)
 */
export function getButtonLabelNode<T>(
  item: T,
  menuConfig: MenuItemConfig<T>,
  selectedConfig?: SelectedItemConfig<T>,
): ReactNode {
  if (selectedConfig?.customLabel) {
    return selectedConfig.customLabel(item);
  }

  if (selectedConfig?.label) {
    return buildLabelFromKeys(item, selectedConfig.label, {
      separator: selectedConfig.separator ?? menuConfig.separator,
      disableSpaceBetween: selectedConfig.disableSpaceBetween ?? menuConfig.disableSpaceBetween,
    });
  }

  if (menuConfig.customLabel) {
    return menuConfig.customLabel(item);
  }

  return buildLabelFromKeys(item, menuConfig.label, {
    separator: menuConfig.separator,
    disableSpaceBetween: menuConfig.disableSpaceBetween,
  });
}

function getPlainTextFromNode(node: ReactNode): string | undefined {
  if (typeof node === "string" || typeof node === "number") {
    return String(node);
  }
  return undefined;
}

/**
 * Builds the multi-selection trigger label as one plain string joined by
 * `separator`. Returns null when any item resolves to a ReactNode (customLabel),
 * so the caller can fall back to the node-based flex layout.
 */
export function getMultiSelectionPlainText<T>(
  items: T[],
  menuConfig: MenuItemConfig<T>,
  selectedConfig?: SelectedItemConfig<T>,
  separator = ", ",
): string | null {
  if (items.length === 0) return null;
  let label = "";
  for (let index = 0; index < items.length; index++) {
    const part = getButtonLabelPlainText(items[index], menuConfig, selectedConfig);
    if (part === undefined) return null;
    if (index > 0) label += separator;
    label += part;
  }
  return label;
}

/**
 * Obtém o texto puro do label para uso em `title` no botão (tooltip nativo).
 * Mesma prioridade do getButtonLabelNode.
 */
export function getButtonLabelPlainText<T>(
  item: T,
  menuConfig: MenuItemConfig<T>,
  selectedConfig?: SelectedItemConfig<T>,
): string | undefined {
  if (selectedConfig?.customLabel) {
    return getPlainTextFromNode(selectedConfig.customLabel(item));
  }

  if (selectedConfig?.label) {
    return buildLabelFromKeys(item, selectedConfig.label, {
      separator: selectedConfig.separator ?? menuConfig.separator,
      disableSpaceBetween: selectedConfig.disableSpaceBetween ?? menuConfig.disableSpaceBetween,
    });
  }

  if (menuConfig.customLabel) {
    return getPlainTextFromNode(menuConfig.customLabel(item));
  }

  return buildLabelFromKeys(item, menuConfig.label, {
    separator: menuConfig.separator,
    disableSpaceBetween: menuConfig.disableSpaceBetween,
  });
}

/**
 * Obtém o ReactNode do startNode para o botão quando um item está selecionado.
 * Prioridade:
 * 1. selectedItemConfig.customStartNode (substitui o padrão)
 * 2. selectedItemConfig.disableStartNode === true → null
 * 3. menuItemConfig.customStartNode (padrão, se existir)
 */
export function getButtonStartNode<T>(
  item: T,
  menuConfig: MenuItemConfig<T>,
  selectedConfig?: SelectedItemConfig<T>,
): ReactNode | null {
  if (selectedConfig?.customStartNode) {
    return selectedConfig.customStartNode(item);
  }

  if (selectedConfig?.disableStartNode) {
    return null;
  }

  if (menuConfig.customStartNode) {
    return menuConfig.customStartNode(item);
  }

  return null;
}

/**
 * Obtém o ReactNode do label para o menu item.
 * Prioridade:
 * 1. itemConfig.customLabel
 * 2. itemConfig.label (com buildLabelFromKeys)
 */
export function getLabelNode<T>(item: T, itemConfig: MenuItemConfig<T>): ReactNode {
  if (itemConfig.customLabel) return itemConfig.customLabel(item);
  return buildLabelFromKeys(item, itemConfig.label, {
    separator: itemConfig.separator,
    disableSpaceBetween: itemConfig.disableSpaceBetween,
  });
}

/** Default labels; every one can be overridden via props. */
export const DEFAULT_PLACEHOLDER = "Select...";
export const DEFAULT_SEARCH_PLACEHOLDER = "Search...";
export const DEFAULT_EMPTY_MESSAGE = "No results found";
export const DEFAULT_LOADING_MESSAGE = "Loading...";
export const DEFAULT_REMOTE_ERROR_MESSAGE =
  "Could not load the options. Close and reopen this field to try again.";
export const DEFAULT_EMPTY_OPTION_LABEL = "No selection";
export const DEFAULT_CLEAR_BUTTON_LABEL = "Clear selection";
export const DEFAULT_LOAD_MORE_LABEL = "Load more";
export const DEFAULT_EXPAND_ALL_LABEL = "Expand all";
export const DEFAULT_COLLAPSE_ALL_LABEL = "Collapse all";

import { useCallback, useEffect, useRef, useState } from "react";

/** Initial attempt + retries. */
const MAX_ATTEMPTS = 3;
/** HTTP statuses that are never retried (auth/permission problems). */
const NON_RETRYABLE_STATUS = new Set([401, 403]);

/**
 * Module-level cache shared by every mounted Combobox: two fields using the same
 * `remote.identifier` read each other's options without a second request.
 * Runtime is untyped on purpose (generic stores across instances); the single
 * cast lives at the read site below.
 */
const remoteCache = new Map<string, unknown[]>();

/**
 * HTTP-ish status detection: supports `{ status }` and axios-like `{ response: { status } }` errors.
 * Lets retry logic skip auth/permission failures without depending on any HTTP client.
 */
function getErrorStatusCode(error: unknown): number | null {
  if (!error || typeof error !== "object") return null;
  const status = (error as { status?: unknown }).status;
  if (typeof status === "number") return status;
  const response = (error as { response?: { status?: unknown } }).response;
  if (response && typeof response === "object") {
    const responseStatus = (response as { status?: unknown }).status;
    if (typeof responseStatus === "number") return responseStatus;
  }
  return null;
}

/**
 * The one remote-loading engine used by both Combobox variants.
 *
 * Semantics:
 * - fetch runs whenever `enabled` turns true (caller maps "dropdown open" to it);
 * - cache-first: `cacheKey` present in the global cache wins over a request,
 *   unless `refreshOnOpen` forces a revalidation;
 * - in-flight requests are superseded: starting a new fetch (or changing the
 *   cache key) aborts the previous one, and a superseded request never writes
 *   state or cache. Stale results can never leak into the new key;
 * - errors clear the cache for the key so the next enable retries; transient
 *   failures retry up to MAX_ATTEMPTS, auth/permission statuses never retry.
 */
export function useRemoteItems<T>(
  fetch: ((signal: AbortSignal) => Promise<T[]>) | undefined,
  cacheKey: string | null,
  options?: { enabled?: boolean; refreshOnOpen?: boolean },
): { items: T[]; error: unknown | null; isLoading: boolean } {
  const { enabled = false, refreshOnOpen = false } = options ?? {};

  // Latest fetch closure without needing it in effect deps.
  const fetchRef = useRef(fetch);
  fetchRef.current = fetch;

  const [state, setState] = useState<{
    items: T[];
    error: unknown | null;
    fetching: boolean;
  }>({ items: [], error: null, fetching: false });
  const abortRef = useRef<AbortController | null>(null);

  const runFetch = useCallback(async (key: string, force: boolean) => {
    const doFetch = fetchRef.current;
    if (!doFetch) return;
    if (!force && remoteCache.has(key)) return;

    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setState({ items: [], error: null, fetching: true });

    for (let attempt = 0; ; attempt++) {
      try {
        const items = await doFetch(controller.signal);
        if (controller.signal.aborted) return; // superseded: never write stale data
        remoteCache.set(key, items);
        setState({ items, error: null, fetching: false });
        return;
      } catch (error) {
        if (controller.signal.aborted) return; // superseded: never write stale errors
        const status = getErrorStatusCode(error);
        if (attempt < MAX_ATTEMPTS - 1 && !NON_RETRYABLE_STATUS.has(status ?? -1)) continue;
        remoteCache.delete(key);
        setState({ items: [], error, fetching: false });
        return;
      }
    }
  }, []);

  // When the cache key changes (new remote or new search text), abandon any
  // in-flight request for the previous key and surface the fresh key's data.
  useEffect(() => {
    abortRef.current?.abort();
    if (!cacheKey) return;
    const cached = remoteCache.get(cacheKey);
    setState({ items: (cached ?? []) as T[], error: null, fetching: false });
  }, [cacheKey]);

  useEffect(() => {
    if (!enabled || !cacheKey) return;
    void runFetch(cacheKey, refreshOnOpen);
  }, [cacheKey, enabled, refreshOnOpen, runFetch]);

  useEffect(() => () => abortRef.current?.abort(), []);

  return { items: state.items, error: state.error, isLoading: state.fetching };
}
